234:         const location = redirectAuthFailure.url || response.headers.get('location') || defaultRedirectAuthFailureUrl;
235:         navigate({ to: location });
236: 
237:         const rejectAuthFailures = fetchInit.rejectAuthFailure === true;
238:         if (!rejectAuthFailures) {
239:           return redirectAuthFailure.resolvePromise
240:             ? (Promise.resolve() as unknown as Promise<FetchResponse>)
241:             : new Promise<FetchResponse>(() => {});
242:         }
243:       }
244: 
245:       // Attempt to download a response body, if it has one
246:       return response
247:         .clone()
248:         .text()
249:         .then(
250:           (responseText) => {
251:             let responseBody = responseText;
252:             try {
253:               responseBody = JSON.parse(responseText);
254:             } catch (err) {
255:               // Server didn't respond with json, so just go with the response text string
256:             }
257: 
258:             // Make the fetch promise go into "rejected" status, with the best
259:             // possible stacktrace and error message.
260:             throw new OpenmrsFetchError(url, response, responseBody, requestStacktrace);
261:           },
262:           () => {
263:             // We weren't able to download a response body for this error.
264:             // Time to just give the best possible stacktrace and error message.
265:             throw new OpenmrsFetchError(url, response, null, requestStacktrace);
266:           },
267:         );
268:     }

